import{z as B,x as p,o as t,c as d,q as o,j as i,D as E,d as l,s as n,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"尾调用优化","description":"","frontmatter":{"title":"尾调用优化","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tail-call-opt.md","filePath":"cs/tail-call-opt.md","lastUpdated":1791063341000}'),C={name:"cs/tail-call-opt.md"};function A(c,a,m,u,D,h){const r=p("Mermaid");return t(),d("div",null,[a[2]||(a[2]=o('<h1 id="尾调用优化" tabindex="-1">尾调用优化 <a class="header-anchor" href="#尾调用优化" aria-label="Permalink to &quot;尾调用优化&quot;">​</a></h1><div class="epigraph"><p>若 `call` 的结果就是当前函数的返回值，且当前帧不再被需要，则可释放帧并把调用改成跳转。空间从线性变成常量。</p><footer>—— 据 Steele, Debunking the &#39;Expensive Procedure Call&#39; Myth；Scheme 报告对 proper tail calls；Appel, Compiling with Continuations 整理</footer></div><p>上一课<a href="/cs/inlining-heuristics">内联</a>用复制换开销。缺口是<strong>不复制</strong>的调用优化：尾调用（TCO）。Scheme 要求 proper tail calls；C 不保证。本课钉何时合法，与<a href="/cs/trampolining">蹦床</a> 后课对照只点名。不写 CPS 变换全文。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>return f(x)</code> 在调用后当前函数无工作。栈上若仍留帧，递归 <code>f</code> 会爆栈。优化：调整参数、<code>jmp f</code>。缺口是<strong>帧与调试/异常</strong>是否还需要当前帧（析构、清理）。</p><p>C++：析构函数使许多「看起来像尾」的调用不是尾。必须先跑清理则不能 TCO，或变成先清理再跳（仍可能）。</p><h3 id="尾递归不是全部尾调用" tabindex="-1">尾递归不是全部尾调用 <a class="header-anchor" href="#尾递归不是全部尾调用" aria-label="Permalink to &quot;尾递归不是全部尾调用&quot;">​</a></h3><p>尾递归是 callee 为自身；TCO 对任意尾位置调用。互递归同样可跳转。不要只教「编译器把递归变循环」这一特例。</p><p><span class="marginnote">Steele 1977。R*RS proper tail calls。Appel 指出 CPS 后所有调用是尾。本课 IR 级：<code>ret (call ...)</code> 形态。</span></p><p><span class="marginnote">数字实例：一百万层深的尾递归，若每帧占 48 字节，不做优化要约 48 MB 栈，而线程默认栈往往只有 1–8 MB，直接段错误；TCO 之后栈占用恒为一帧，深度再大也不涨。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>识别：调用结果立即返回，无待办副作用。ABI：callee 与 caller 约定兼容（参数寄存器），否则要垫片。不同函数尾调用可能要调整栈参数区。</p>',12)),(t(),i(s,null,{default:E(()=>[n(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20RET%5B%22return%20f(args)%22%5D%20--%3E%20CHK%5B%22%E6%97%A0%E5%BE%85%E6%B8%85%E7%90%86%22%5D%0A%20%20CHK%20--%3E%20JMP%5B%22jmp%20f%22%5D%0A%20%20JMP%20--%3E%20STK%5B%22%E5%A4%8D%E7%94%A8%E6%88%96%E5%BC%B9%E5%87%BA%E5%B8%A7%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与内联：小的尾递归可内联成循环；大的只 TCO。不要二者都做导致体爆炸再 TCO 无意义。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：TCO 就是「临走前把工位让给下一个人」——当前函数只剩一件事（返回别人的结果），它把自己的栈帧工位直接改名让 f 用，而不是又到楼上新租一层。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"诊断：语言若保证 TCO，漏优化是 bug；C 则是质量。调试器：帧消失，backtrace 变短——DWARF 可选用虚拟帧。不要在必须精确栈展开的异常路径上静默 TCO 而不更新 unwind。",-1)),a[7]||(a[7]=e("p",null,[e("span",{class:"marginnote"},[l("常见误区：初学者以为「编译器总能把递归变循环」。实际上只有尾位置的调用才有资格：非尾递归每一层都还要拿中间结果继续算，帧必须留着。另外 C 标准根本不保证 TCO，gcc/clang 在 "),e("code",null,"-O2"),l(" 下只是尽力而为，换了编译器或加一句打印就可能爆栈。")])],-1)),(t(),i(s,null,{default:E(()=>[n(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20CALL%5B%22%E4%B8%80%E5%A4%84%E8%B0%83%E7%94%A8%22%5D%20--%3E%20T%7B%22%E7%BB%93%E6%9E%9C%E6%98%AF%E5%90%A6%E7%AB%8B%E5%8D%B3%E8%A2%AB%E8%BF%94%E5%9B%9E%EF%BC%9F%22%7D%0A%20%20T%20--%3E%7C%22%E5%90%A6%22%7C%20NO1%5B%22%E4%B8%8D%E6%98%AF%E5%B0%BE%E4%BD%8D%E7%BD%AE%EF%BC%8C%E4%BF%9D%E7%95%99%20call%22%5D%0A%20%20T%20--%3E%7C%22%E6%98%AF%22%7C%20D%7B%22%E5%BD%93%E5%89%8D%E5%B8%A7%E8%BF%98%E6%9C%89%E5%BE%85%E6%B8%85%E7%90%86%EF%BC%9F%22%7D%0A%20%20D%20--%3E%7C%22%E6%9E%90%E6%9E%84%E5%BE%85%E8%B7%91%22%7C%20NO2%5B%22%E5%85%88%E6%B8%85%E7%90%86%E5%86%8D%E8%B7%B3%EF%BC%8C%E6%88%96%E6%94%BE%E5%BC%83%E4%BC%98%E5%8C%96%22%5D%0A%20%20D%20--%3E%7C%22%E6%97%A0%22%7C%20ABI%7B%22%E8%B0%83%E7%94%A8%E7%BA%A6%E5%AE%9A%E5%85%BC%E5%AE%B9%EF%BC%9F%22%7D%0A%20%20ABI%20--%3E%7C%22%E5%85%BC%E5%AE%B9%22%7C%20YES%5B%22%E4%BC%98%E5%8C%96%E6%88%90%20jmp%EF%BC%8C%E5%B8%A7%E5%A4%8D%E7%94%A8%22%5D%0A%20%20ABI%20--%3E%7C%22%E4%B8%8D%E5%85%BC%E5%AE%B9%22%7C%20SHIM%5B%22%E5%9E%AB%E7%89%87%E8%B0%83%E6%95%B4%E5%90%8E%E5%86%8D%E8%B7%B3%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写完整 CPS。后课默认：尾位置调用可变成跳转。下一课逃逸分析：堆分配能否改栈，与帧寿命相关。</p><p>也不把 TCO 当异步协程的定义。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>尾调用：复用帧，call 变 jmp。</li><li>清理、ABI、异常表限制合法性。</li><li>尾递归是特例；互递归同样适用。</li><li>出处：Steele；Scheme 报告；Appel。</li></ul>',5))])}const S=B(C,[["render",A]]);export{f as __pageData,S as default};
